'use client' // Error boundaries must be Client Components

import { useEffect } from 'react'

export type ErrorPageProps = {
  error: unknown
  retry: () => void
}

// Errors from Server Components arrive with a `digest` for matching server logs
export function isServerError(error: unknown): boolean {
  return error instanceof Error && 'digest' in error && !!error.digest
}

export default function Error({ error, retry }: ErrorPageProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <title>Error - My Blog</title>
      <h1>
        {isServerError(error)
          ? 'An error occurred on server'
          : 'An error occurred on client'}
      </h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => retry()}>Try again</button>
    </div>
  )
}

