import { useEffect } from 'react'
import { isServerError, type ErrorPageProps } from './error'
import '@/styles/globals.css'

// Replaces the root layout when an error is thrown in it, so it must render
// its own <html> and <body>.
export default function GlobalError({ error, retry }: ErrorPageProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <html lang="en">
      <body>
        <title>Error - My Blog</title>
        <div className="error-page">
          <h1>
            {isServerError(error)
              ? 'An error occurred on server'
              : 'An error occurred on client'}
          </h1>
          <p>Sorry, something went wrong.</p>
          <button onClick={() => retry()}>Try again</button>
        </div>
      </body>
    </html>
  )
}

